int parse_ssl_flag(int flag) {
  flag_struct *fl;

  for(fl = flags; fl->name; fl++) {
    if(fl->ch == flag) {
      if(fl->flag & NEGATE) {
        SSL_print_flags &= ~(fl->flag);
      } else
        SSL_print_flags |= fl->flag;
      break;
    }
  }

  return 0;
}

static int parse_ssl_flags(char *str) {
  char *x, *y;
  flag_struct *fl;
  int bang;

  y = str;

  while((x = strtok(y, ","))) {
    y = 0;

    if(*x == '!') {
      bang = 1;
      x++;
    } else
      bang = 0;
    for(fl = flags; fl->name; fl++) {
      if(!strcmp(x, fl->name)) {
        if(!bang)
          SSL_print_flags |= fl->flag;
        else
          SSL_print_flags &= ~fl->flag;
        break;
      }
    }
    if(!fl->name) {
      fprintf(stderr, "SSL: Bad flag %s\n", x);
    }
  }

  return 0;
}

