609	static int decode_HandshakeType_Certificate(ssl_obj *ssl,
610	                                            int dir,
611	                                            segment *seg,
612	                                            Data *data) {
613	  UINT4 cert_list_len, exlen, ex;
614	  Data cert;
615	  Data cert_list, cert_exts;
616	  int r;
617	
618	  struct json_object *jobj;
619	  jobj = ssl->cur_json_st;
620	  json_object_object_add(jobj, "handshake_type",
621	                         json_object_new_string("Certificate"));
622	  extern decoder extension_decoder[];
623	
624	  LF;
625	  ssl_update_handshake_messages(ssl, data);
626	  if(ssl->version == TLSV13_VERSION) {
627	    SSL_DECODE_OPAQUE_ARRAY(ssl, "certificate request context", -((1 << 7) - 1),
628	                            0, data, NULL);
629	  }
630	  SSL_DECODE_UINT24(ssl, "certificates len", 0, data, &cert_list_len);
631	  if(cert_list_len > data->len) {
632	    fprintf(stderr,
633	            "Error: short certificate list: expected %u got %d\n",
634	            cert_list_len, data->len);
635	    ERETURN(R_EOD);
636	  }
637	
638	  INIT_DATA(cert_list, data->data, cert_list_len);
639	  data->data += cert_list_len;
640	  data->len -= cert_list_len;
641	
642	  json_object_object_add(jobj, "cert_chain", json_object_new_array());
643	
644	  while(cert_list.len) {
645	    SSL_DECODE_OPAQUE_ARRAY(ssl, "certificate", -((1 << 23) - 1), 0,
646	                            &cert_list, &cert);
647	    sslx_print_certificate(ssl, &cert, P_ND);
648	    if(ssl->version == TLSV13_VERSION) {  // TLS 1.3 has certificate extensions
649	      SSL_DECODE_UINT16(ssl, "certificate extensions len", 0, &cert_list,
650	                        &exlen);
651	      if(exlen > cert_list.len) {
652	        fprintf(stderr,
653	                "Error: short certificate extensions: expected %u got %d\n",
654	                exlen, cert_list.len);
655	        ERETURN(R_EOD);
656	      }
657	
658	      INIT_DATA(cert_exts, cert_list.data, exlen);
659	      cert_list.data += exlen;
660	      cert_list.len -= exlen;
661	
662	      while(cert_exts.len) {
663	        int before = cert_exts.len;
664	        SSL_DECODE_UINT16(ssl, "extension type", 0, &cert_exts, &ex);
665	        if(ssl_decode_switch(ssl, extension_decoder, ex, dir, seg,
666	                             &cert_exts) == R_NOT_FOUND) {
667	          if((r = decode_extension(ssl, dir, seg, &cert_exts)))
668	            ERETURN(r);
669	          P_(P_RH) {
670	            explain(ssl, "Extension type: %u not yet implemented in ssldump\n",
671	                    ex);
672	          }
673	          continue;
674	        }
675	        if(cert_exts.len >= before) {
676	          fprintf(stderr, "Error: certificate extension %u made no progress\n",
677	                  ex);
678	          ERETURN(R_EOD);
679	        }
680	        LF;
681	      }
682	    }
683	  }
684	
685	  return 0;
686	}
